/*
 * O composer de mensagem do flarum/messages na forma do composer do Discourse
 * para mensagens pessoais (`creatingPrivateMessage`), dentro da mesma casca
 * do composer do tema (`composer/installComposerShell.tsx`):
 *
 *   alça · "✉ Criar mensagem ▾" ...................... «  ⤢  —  ✕
 *   [👤 ana ✕] Adicionar usuários(as) ou grupos ▾ |
 *   Título
 *   texto                                  | prévia
 *   B I H 🔗 " </> … ................ Descartar  [Enviar mensagem]
 *
 * Na resposta, só a ação ("↪ Mensagem") e o link para a mensagem quando ela
 * não está aberta atrás do composer — como o Discourse ao responder.
 *
 * A casca já cuida do rodapé (Descartar + botão primário sem ícone), dos
 * botões do canto, da prévia ao lado e das alturas; aqui entram só os campos
 * do cabeçalho e os rótulos. O MessageComposer vem num pedaço carregado sob
 * demanda: é estendido pelo nome do módulo.
 */
import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import Stream from 'flarum/common/utils/Stream';
import RecipientChooser from './RecipientChooser';
import ComposerActionTitle from '../../composer/ComposerActionTitle';
import { isExtensionEnabled, t } from '../../utils/settings';
import { boxesOn, dialogHref, dialogTitle, messageGroup, messagesOn } from './util';
const COMPOSER = 'ext:flarum/messages/forum/components/MessageComposer';

/** O `max_allowed_message_recipients` do Discourse (o backend confere). */
const MAX_RECIPIENTS = 30;

/** Os rótulos de ícone das ações do Discourse (`envelope` e `share`). */
const ICON_NEW = 'far fa-envelope';
const ICON_REPLY = 'fas fa-arrow-up-from-bracket';

/**
 * O placeholder do composer de tópico do tema (o do Discourse, dizendo só o
 * que este fórum faz) — a mesma regra de `composer/installComposerShell.tsx`,
 * que não a exporta.
 */
function bodyPlaceholder() {
  const markdown = isExtensionEnabled('flarum-markdown');
  const upload = isExtensionEnabled('fof-upload') && !!app.forum.attribute('fof-upload.canUpload');
  const key = markdown ? upload ? 'body_placeholder_markdown_upload' : 'body_placeholder_markdown' : upload ? 'body_placeholder_upload' : 'body_placeholder';
  return t(`composer.shell.${key}`);
}
/**
 * A primeira linha (`.reply-to`): "✉ Criar mensagem ▾" na mensagem nova, com
 * o menu de ações do Discourse (trocar por um tópico), e "↪ Mensagem" na
 * resposta. Minimizado, vira a barra do rascunho.
 */
class MessageAction extends Component {
  view() {
    const {
      dialog
    } = this.attrs;
    if (app.composer.position === 'minimized') {
      const text = dialog ? dialogTitle(dialog) : this.attrs.title() || this.attrs.recipients()[0]?.username() || t('messages.composer.action_new');
      return m("div", {
        className: "CanelaComposerAction CanelaComposerAction--draft"
      }, m(Icon, {
        name: dialog ? ICON_REPLY : ICON_NEW
      }), m("span", {
        className: "CanelaComposerAction-draftText"
      }, text));
    }

    // A mensagem nova usa o mesmo cabeçalho do composer de tópico (com o
    // menu de ações dele); a resposta tem o rótulo parado e o link.
    if (!dialog) return m(ComposerActionTitle, {
      kind: "message",
      label: t('messages.composer.action_new'),
      icon: ICON_NEW,
      title: this.attrs.title
    });
    return m("div", {
      className: "CanelaComposerAction",
      role: "heading",
      "aria-level": 1
    }, this.replyTrigger(), this.targetLink(dialog));
  }
  replyTrigger() {
    return m("span", {
      className: "CanelaComposerAction-trigger CanelaComposerAction-trigger--static"
    }, m(Icon, {
      name: ICON_REPLY
    }), m("span", {
      className: "CanelaComposerAction-label"
    }, t('messages.composer.action_reply')));
  }

  /** "🔗 título": só quando a mensagem não está aberta atrás do composer. */
  targetLink(dialog) {
    if (m.route.param('id') === dialog.id()) return null;
    const title = dialogTitle(dialog);
    return m(Link, {
      className: "CanelaComposerAction-target",
      href: dialogHref(dialog),
      title: title,
      onclick: event => {
        if (app.composer.position === 'fullScreen') {
          app.composer.minimize();
          event.stopPropagation();
        }
      }
    }, m(Icon, {
      name: "fas fa-link"
    }), m("span", {
      className: "CanelaComposerAction-targetLabel"
    }, title));
  }
}
export default function installComposer() {
  flarum.reg.onLoad('flarum-messages', 'forum/components/MessageComposer', module => {
    // "Enviar mensagem" / "Responder" e o placeholder do editor do tema.
    override(module, 'initAttrs', function (original, attrs) {
      if (messagesOn()) {
        attrs.submitLabel = attrs.submitLabel || (attrs.replyingTo ? t('messages.composer.submit_reply') : t('messages.composer.submit'));
        attrs.placeholder = attrs.placeholder || bodyPlaceholder();
      }
      return original(attrs);
    });
  });
  extend(COMPOSER, 'oninit', function () {
    const fields = this.composer?.fields;
    if (fields && !fields.canelaTitle) fields.canelaTitle = Stream('');
    if (fields && !fields.canelaGroup) fields.canelaGroup = Stream(null);
  });
  extend(COMPOSER, 'headerItems', function (items) {
    if (!messagesOn()) return;
    const dialog = this.attrs.replyingTo;
    const fields = this.composer.fields;
    const put = (key, content, priority) => {
      if (items.has(key)) items.setContent(key, content).setPriority(key, priority);else items.add(key, content, priority);
    };
    put('title', m(MessageAction, {
      dialog: dialog,
      title: () => fields.canelaTitle ? fields.canelaTitle() : '',
      recipients: () => this.recipients()
    }), 1000);
    if (dialog) {
      // Na resposta os destinatários são os da conversa: nada a escolher.
      if (items.has('recipients')) items.remove('recipients');
      return;
    }
    put('recipients', m("div", {
      className: "CanelaComposerFields CanelaMessageFields"
    }, m(RecipientChooser, {
      recipients: this.recipients,
      max: boxesOn() ? MAX_RECIPIENTS : 1,
      group: messageGroup() ? fields.canelaGroup : undefined,
      groupContact: true
    }), m("div", {
      className: "CanelaComposerFields-cell CanelaMessageFields-rest",
      "aria-hidden": "true"
    })), 500);

    // O título só é guardado com o backend do tema (a coluna é dele).
    if (boxesOn()) {
      put('canelaMessageTitle', m("h3", null, m("input", {
        className: "FormControl CanelaMessageTitle-input",
        type: "text",
        value: fields.canelaTitle(),
        maxlength: 255,
        placeholder: t('messages.composer.title_placeholder'),
        "aria-label": t('messages.composer.title_placeholder'),
        oninput: event => fields.canelaTitle(event.target.value),
        onkeydown: event => {
          if (event.key === 'Enter') {
            event.preventDefault();
            document.querySelector('.Composer .TextEditor-editor')?.focus();
          }
        }
      })), 400);
    }
  });
  extend(COMPOSER, 'data', function (data) {
    if (!messagesOn() || this.attrs.replyingTo || !boxesOn() || !data) return;

    // A API aceita um destinatário em `users`; os outros vão em `canelaUsers`
    // e o tema abre uma conversa nova com todos.
    const recipients = this.recipients();
    if (recipients.length > 1) {
      data.users = [{
        id: recipients[0].id()
      }];
      data.canelaUsers = recipients.slice(1).map(user => Number(user.id()));
    }
    const title = String(this.composer.fields.canelaTitle?.() || '').trim();
    if (title) data.canelaTitle = title;
  });

  // Mensagem sem destinatário não sai: o Discourse desabilita o envio.
  override(COMPOSER, 'onsubmit', function (original) {
    if (messagesOn() && !this.attrs.replyingTo && !this.recipients().length) {
      app.alerts.show({
        type: 'error'
      }, t('messages.composer.recipients_missing'));
      document.querySelector('.Composer .CanelaRecipients-input')?.focus();
      return;
    }
    return original();
  });
}
flarum.reg.add('ramon-canela', 'forum/features/messages/composer', installComposer);