/*
 * Reações nas mensagens privadas, como o discourse-reactions nas mensagens do
 * Discourse — com o mesmo desenho das reações dos posts do tema
 * (`thirdparty/reactions.tsx`): o resumo à esquerda da barra (até três emojis
 * e o total; o clique mostra quem reagiu) e o botão de reagir com o seletor
 * no hover/clique, que mostra o emoji escolhido depois de reagir (clicar nele
 * desfaz).
 *
 * A lista é a do fof/reactions quando ele está ligado (os emojis desenhados
 * pelo componente dele, as classes do seletor dele); sem ele, a lista padrão
 * do Discourse em emoji Unicode. Sem a tabela das reações, nada aparece.
 */
import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Modal from 'flarum/common/components/Modal';
import Avatar from 'flarum/common/components/Avatar';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import abbreviateNumber from 'flarum/common/utils/abbreviateNumber';
import classList from 'flarum/common/utils/classList';
import { extModule } from '../../thirdparty/settings';
import { enabledReactions } from '../../thirdparty/reactions';
import { t } from '../../utils/settings';
import { messagesOn } from './util';
const MESSAGE = 'ext:flarum/messages/forum/components/Message';

/** Quantos emojis o resumo mostra, como nos posts. */
const SUMMARY_EMOJIS = 3;

/** As reações padrão do discourse-reactions, quando o fof/reactions não está ligado. */
const UNICODE = {
  heart: '❤️',
  '+1': '👍',
  laughing: '😆',
  open_mouth: '😮',
  cry: '😢',
  tada: '🎉',
  rocket: '🚀'
};
function config() {
  const value = app.forum?.attribute('canelaMessageReactions');
  return value && typeof value === 'object' && value.enabled ? value : null;
}

/** As chaves das reações que dá para escolher agora: as habilitadas do fof, na ordem dele. */
function available(cfg) {
  if (!cfg.fof) return cfg.list;
  return enabledReactions().map(reaction => String(reaction.id()));
}

/** A chave do ❤️ (o clique direto no coração), se ele estiver na lista. */
function heartKey(cfg, keys) {
  if (!cfg.fof) return keys.indexOf('heart') !== -1 ? 'heart' : null;
  return keys.find(key => app.store.getById('reactions', key)?.identifier?.() === 'heart') || null;
}

/** O emoji de uma chave: o componente do fof/reactions ou o Unicode do Discourse. */
function emoji(cfg, key) {
  if (cfg.fof) {
    const ReactionComponent = extModule('fof-reactions', 'common/components/ReactionComponent');
    const reaction = app.store.getById('reactions', key);
    return ReactionComponent && reaction ? m(ReactionComponent, {
      reaction
    }) : null;
  }
  return m("span", {
    className: "emoji CanelaUnicodeEmoji"
  }, UNICODE[key] || key);
}
function label(cfg, key) {
  if (cfg.fof) return String(app.store.getById('reactions', key)?.identifier?.() || key);
  return key;
}
function summary(message) {
  const value = message.attribute('canelaReactions');
  return value && typeof value === 'object' ? {
    counts: value.counts || {},
    mine: value.mine ?? null
  } : {
    counts: {},
    mine: null
  };
}
function react(message, key) {
  return app.request({
    method: 'POST',
    url: `${app.forum.attribute('apiUrl')}/dialog-messages/${message.id()}/canela-react`,
    body: {
      reaction: key
    }
  }).then(result => {
    message.pushAttributes({
      canelaReactions: result
    });
    // O post do stream guarda a árvore (SubtreeRetainer): a "frescura"
    // muda para ele redesenhar.
    message.freshness = new Date();
    m.redraw();
  });
}
/** Quem reagiu (`.discourse-reactions-state-panel`), agrupado por reação. */
class ReactorsModal extends Modal {
  groups = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/dialog-messages/${this.attrs.message.id()}/canela-reactions`
    }).then(result => {
      this.groups = result.groups || [];
      m.redraw();
    }).catch(() => {
      this.groups = [];
      m.redraw();
    });
  }
  className() {
    return 'Modal--small ReactionsModal CanelaMessageReactorsModal';
  }
  title() {
    return t('messages.reactions.reactors_title');
  }
  content() {
    const cfg = config();
    if (!this.groups || !cfg) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, null));
    return m("div", {
      className: "Modal-body"
    }, this.groups.map(group => m("div", {
      className: "CanelaMessageReactors-group"
    }, m("div", {
      className: "ReactionsModal-groupHeader CanelaMessageReactors-header"
    }, emoji(cfg, group.reaction), m("span", {
      className: "ReactionsModal-reactionCount"
    }, group.users.length)), m("ul", {
      className: "CanelaMessageReactors-users"
    }, group.users.map(user => {
      const model = app.store.getById('users', user.id);
      return m("li", {
        className: "ReactionsModal-user"
      }, model ? m(Avatar, {
        user: model
      }) : user.avatarUrl ? m("img", {
        className: "Avatar",
        src: user.avatarUrl,
        alt: ""
      }) : null, model ? m(Link, {
        href: app.route.user(model)
      }, user.displayName) : m("span", null, user.displayName));
    })))));
  }
}

/**
 * O botão de reagir com o seletor (`.discourse-reactions-reaction-button` +
 * `.discourse-reactions-picker`), nas classes do fof/reactions para herdar o
 * desenho dos posts. Já reagiu: o emoji escolhido, que desfaz ao clicar.
 */
class ReactButton {
  open = false;
  pressTimer = 0;
  suppressClick = false;
  element = null;
  oncreate(vnode) {
    this.element = vnode.dom;
  }
  onremove() {
    window.clearTimeout(this.pressTimer);
    document.removeEventListener('pointerdown', this.outside, true);
  }
  outside = event => {
    if (this.element && !this.element.contains(event.target)) this.setOpen(false);
  };

  /**
   * Abre/fecha mexendo na classe direto: a mensagem fica guardada pelo
   * SubtreeRetainer e não se redesenha por um estado só deste botão.
   */
  setOpen(open) {
    this.open = open;
    this.element?.querySelector('.Reactions--react')?.classList.toggle('is-open', open);
    this.element?.querySelector('.CommentPost--Reactions')?.classList.toggle('mobile-show', open);
    if (open) document.addEventListener('pointerdown', this.outside, true);else document.removeEventListener('pointerdown', this.outside, true);
  }

  /** No toque, segurar o coração abre o seletor (o clique que vem depois não reage). */
  press(event) {
    this.suppressClick = false;
    if (event.pointerType === 'mouse') return;
    window.clearTimeout(this.pressTimer);
    this.pressTimer = window.setTimeout(() => {
      this.suppressClick = true;
      this.setOpen(true);
    }, 400);
  }
  view(vnode) {
    const {
      message,
      cfg
    } = vnode.attrs;
    const mine = summary(message).mine;
    const keys = available(cfg);
    const heart = heartKey(cfg, keys);
    const reactLabel = t('messages.reactions.react');
    return m("div", {
      className: "Reactions CanelaMessageReact"
    }, m("div", {
      className: classList('Reactions--react', {
        'is-open': this.open
      })
    }, mine ? m(Button, {
      className: "Button Button--link Reactions--ShowReactions CanelaReactions-mine",
      title: t('messages.reactions.unreact'),
      "aria-label": t('messages.reactions.unreact'),
      onclick: () => react(message, null).catch(() => {})
    }, mine === heart ? m(Icon, {
      name: "fas fa-heart",
      className: "Button-icon CanelaMessageReact-liked"
    }) : emoji(cfg, mine)) :
    // O coração, como nos posts e no Discourse: o clique reage com o
    // ❤️; o hover (ou o toque longo) abre o seletor.
    m(Button, {
      className: "Button Button--link Reactions--ShowReactions CanelaMessageReact-heart",
      icon: "far fa-heart",
      title: reactLabel,
      "aria-label": reactLabel,
      "aria-haspopup": "menu",
      onpointerdown: event => this.press(event),
      onpointerup: () => window.clearTimeout(this.pressTimer),
      onpointercancel: () => window.clearTimeout(this.pressTimer),
      onclick: () => {
        if (this.suppressClick) {
          this.suppressClick = false;
          return;
        }
        if (heart) {
          this.setOpen(false);
          react(message, heart).catch(() => {});
        } else {
          this.setOpen(!this.open);
        }
      }
    }), m("div", {
      className: classList('CommentPost--Reactions Reactions--reactions', {
        'mobile-show': this.open
      }),
      role: "menu"
    }, m("ul", {
      className: "Reactions--Ul"
    }, keys.map(key => m("li", null, m(Button, {
      className: classList('Button Button--link', {
        active: key === mine
      }),
      title: label(cfg, key),
      "aria-label": label(cfg, key),
      onclick: () => {
        this.setOpen(false);
        react(message, key === mine ? null : key).catch(() => {});
      }
    }, emoji(cfg, key))))))));
  }
}
export default function installMessageReactions() {
  extend(MESSAGE, 'actionItems', function (items) {
    const cfg = config();
    if (!messagesOn() || !cfg) return;
    const message = this.attrs.message;
    const {
      counts
    } = summary(message);
    const list = Object.keys(counts).map(key => [key, Number(counts[key]) || 0]).filter(([, count]) => count > 0).sort((a, b) => b[1] - a[1]);

    // O resumo à esquerda: até três emojis e o total; o clique mostra quem reagiu.
    if (list.length) {
      const total = list.reduce((sum, [, count]) => sum + count, 0);
      const text = t('thirdparty.reactions.summary', {
        count: total
      });
      items.add('canelaReactions', m(Button, {
        className: "Button Button--flat CanelaPostAction CanelaReactions",
        "aria-label": text,
        title: text,
        onclick: () => app.modal.show(ReactorsModal, {
          message
        })
      }, m("span", {
        className: "CanelaReactions-list"
      }, list.slice(0, SUMMARY_EMOJIS).map(([key]) => m("span", {
        className: "CanelaReactions-emoji"
      }, emoji(cfg, key)))), m("span", {
        className: "CanelaReactions-count"
      }, abbreviateNumber(total))), 1050);
    }
    items.add('react', m(ReactButton, {
      message,
      cfg
    }), 60);
  });
}
flarum.reg.add('ramon-canela', 'forum/features/messages/reactions', installMessageReactions);